// Permission helpers (generated by engineering-platform frontend-permission asset)
// UX-only visibility helpers. Backend @RequirePermission is the real security boundary.
import { useAuthStore } from '../stores/auth';

/** True when the current user holds the given permission code (or is admin-ish via *). */
export function hasPermission(permission: string): boolean {
  const auth = useAuthStore();
  const granted = auth.permissions;
  return granted.includes('*') || granted.includes(permission);
}

/** True when the user holds ANY of the given permission codes. */
export function hasAnyPermission(permissions: string[]): boolean {
  return permissions.some((p) => hasPermission(p));
}

/** Install v-permission directive: v-permission="'code'" hides element when lacking permission. */
export function installPermissionDirective(app: { directive: (name: string, def: unknown) => void }): void {
  app.directive('permission', {
    mounted(el: HTMLElement, binding: { value: string | string[] }) {
      const codes = Array.isArray(binding.value) ? binding.value : [binding.value];
      if (!hasAnyPermission(codes)) {
        el.parentNode?.removeChild(el);
      }
    },
  });
}
